 "lean_claims": [
  {"theorem": "curlRemainder_waveClass", "line": 39, "plain": "Hypotheses: the phase normals n_Φ^(n) have uniform polynomial jets on the phase domain; a ∈ W_α (weight √ζ·P); b > 0 and b ≤ |n_Φ^(n)(x)| ≤ M for x in s.domain; κ ≥ 0; V_r ∈ M_{-κ}, V_θ ∈ M_0, V_z ∈ M_1, 1/R ∈ M_0; and |1/K_n| ≤ C·ε_n^{1/2}·slow_n^p. Conclusion: n ↦ curlRemainder(K_n, R, V^(n), coefficient(R, V^(n), Φ_n, a_n)) belongs to W_{α+1/2−κ} with the same weight √ζ·P."}
 ],
 "paper_claims": [
  {"ref": "Lemma 9.2", "plain": "If w ∈ W_α is a wave and v is a mean field with tangential components in M_μ and radial component in M_{μ+1}, then the nonzero harmonics of (w·∇*)v + (v·∇*)w lie in W_{α+μ−1/2}. For two curl-generated waves with the same label, the nonzero harmonics of the symmetric product lie in W_{α+α′−κs} and the zero harmonic lies in M_{α+α′−κs}. Distinct labels give zero products."}
 ],
